using System.Web.Http;                   // Web API 2 — NOT available in .NET 10
using System.Web.Http.Description;       // IHttpActionResult, ApiExplorer
using System.Web.Mvc;                    // MVC 5 — NOT available in .NET 10

// Web API 2 controller
public class OrdersController : ApiController
{
    [Route("api/orders/{id:int}")]
    [ResponseType(typeof(OrderDto))]
    public IHttpActionResult GetOrder(int id)
    {
        var order = _service.Find(id);
        if (order == null)
            return NotFound();            // ApiController.NotFound()
        return Ok(order);                 // ApiController.Ok(T)
    }

    // Web API 2: model binding from URI uses [FromUri]; body uses [FromBody].
    // ASP.NET Core: [FromRoute] / [FromQuery] / [FromBody] / [FromForm].
    public IHttpActionResult CreateOrder([FromBody] CreateOrderRequest request)
    {
        if (!ModelState.IsValid)
            return BadRequest(ModelState); // returns 400 with ModelState
        var id = _service.Create(request);
        return Created($"api/orders/{id}", new { id });
    }

    // MVC 5 ActionResult pattern for a view-returning action
    public class HomeController : Controller
    {
        public ActionResult Index()
        {
            ViewBag.Title = "Home";
            return View();
        }

        [ValidateAntiForgeryToken]
        [HttpPost]
        public ActionResult Submit(FormModel model)
        {
            if (!ModelState.IsValid) return View(model);
            return RedirectToAction("Index");
        }
    }
}
